window.__SHOP__.adressform=window.__SHOP_ADRESSFORM__||'datei';
window.__SHOP__.tiefe=!!window.__SHOP_TIEFE__;











const EUR = (n) => n.toFixed(2).replace('.', ',') + ' €';











const STEUERZEICHEN = /[\u0000-\u001F\u007F\u0085\u2028\u2029]/;
const STEUERZEICHEN_FOLGE = /[\u0000-\u001F\u007F\u0085\u2028\u2029]+/g;















const textZeile = (wert) => String(wert ?? '').replace(STEUERZEICHEN_FOLGE, ' ').trim();













const csvFeld = (wert) => textZeile(wert).replaceAll(';', ',');











const hatSteuerzeichen = (wert) => STEUERZEICHEN.test(String(wert ?? ''));







const LUECKE = (bezeichnung) => `[[ ${bezeichnung} — FEHLT ]]`;


































const GEBIETSSTAND = Object.freeze({
  stand: '2026-08-16',
  quelle:
    'BMLUK und Landesquellen (Sekundärquellen, mehrfach unabhängig; Oberösterreich amtlich durch das Land)',
  vorbehalt:
    'Bezirksliste aus Sekundärquellen — sieben der zehn Bezirke unabhängig bestätigt, Vorarlberg indirekt; vor einer Veröffentlichung am Verordnungstext gegenzuprüfen.',
});






const AUSNAHMEN_VORSORGEGEBIET = Object.freeze([
  { name: 'Wien', bundesland: 'Wien' },
  { name: 'Güssing', bundesland: 'Burgenland' },
  { name: 'Jennersdorf', bundesland: 'Burgenland' },
  { name: 'Neusiedl am See', bundesland: 'Burgenland' },
  { name: 'Oberwart', bundesland: 'Burgenland' },
  { name: 'Bruck an der Leitha', bundesland: 'Niederösterreich' },
  { name: 'Ried im Innkreis', bundesland: 'Oberösterreich' },
  { name: 'Südoststeiermark', bundesland: 'Steiermark' },
  { name: 'Bregenz', bundesland: 'Vorarlberg' },
  { name: 'Dornbirn', bundesland: 'Vorarlberg' },
  { name: 'Feldkirch', bundesland: 'Vorarlberg' },
]);

const vergleichbar = (wert) =>
  textZeile(wert)
    .toLowerCase()
    .replace(/^bezirk\s+/, '')
    .replace(/\s+/g, ' ')
    .trim();









function vorsorgeauskunft(bezirk) {
  const eingabe = textZeile(bezirk);
  const gesucht = vergleichbar(bezirk);
  const treffer = gesucht
    ? AUSNAHMEN_VORSORGEGEBIET.find((a) => vergleichbar(a.name) === gesucht) ?? null
    : null;

  const saetze = [];
  if (!gesucht) {
    saetze.push('Kein Bezirk angegeben — die Auskunft braucht den Bezirk der Baustelle.');
  } else if (treffer) {
    saetze.push(
      `${treffer.name} (${treffer.bundesland}) steht auf der Ausnahmeliste und ist kein Radonvorsorgegebiet — die bauliche Vorsorgepflicht für Neubauten gilt dort nicht.`,
    );
  } else {
    saetze.push(
      `„${eingabe}" steht nicht auf der Ausnahmeliste (Wien und zehn Bezirke) — der Bezirk gilt damit als Radonvorsorgegebiet: bauliche Vorsorge im Neubau nach Landesrecht und ÖNORM S 5280-2.`,
    );
  }
  saetze.push(
    'Ob zusätzlich Schutzgebiets-Pflichten gelten (104 Gemeinden, Anlage 1 Radonschutzverordnung), beantwortet nur die amtliche Liste auf Gemeindeebene.',
  );

  return {
    eingabe,
    beantwortet: Boolean(gesucht),
    ausgenommen: Boolean(treffer),
    gebiet: treffer,
    text: saetze.join(' '),
    ...GEBIETSSTAND,
  };
}












const MARGENUNTERGRENZE = 0.32;
const UST_SATZ = 0.20;


function cent(betrag) {
  return Math.round((betrag + Number.EPSILON) * 100) / 100;
}






function einkaufspreis(uvpNetto, haendlerrabatt) {
  if (uvpNetto <= 0) throw new Error('UVP muss positiv sein');
  if (haendlerrabatt < 0 || haendlerrabatt >= 1) {
    throw new Error('Händlerrabatt muss zwischen 0 und 1 liegen');
  }
  return cent(uvpNetto * (1 - haendlerrabatt));
}









function verkaufspreis(ekNetto, zielmarge, uvpNetto = Infinity) {
  if (zielmarge < 0 || zielmarge >= 1) {
    throw new Error('Zielmarge muss zwischen 0 und 1 liegen');
  }
  return cent(Math.min(ekNetto / (1 - zielmarge), uvpNetto));
}


function rohmarge(ekNetto, vkNetto) {
  if (vkNetto <= 0) return 0;
  return (vkNetto - ekNetto) / vkNetto;
}


















function artikelEinkauf(artikel, lieferant) {
  if (typeof artikel.ekNetto === 'number') {
    if (artikel.ekNetto <= 0) throw new Error(`Einkaufspreis von ${artikel.sku} muss positiv sein`);
    return cent(artikel.ekNetto);
  }
  const rabatt = artikel.haendlerrabattAufUvp ?? lieferant.haendlerrabattAufUvp;
  if (typeof rabatt !== 'number') {
    throw new Error(`Für ${artikel.sku} ist weder Einkaufspreis noch Rabattsatz bekannt`);
  }
  return einkaufspreis(artikel.uvpNetto, rabatt);
}












function kalkuliere(artikel, lieferant, zielmarge) {
  const ekNetto = artikelEinkauf(artikel, lieferant);
  const deckel = typeof artikel.uvpNetto === 'number' ? artikel.uvpNetto : Infinity;
  const vkNetto = verkaufspreis(ekNetto, zielmarge, deckel);
  const marge = rohmarge(ekNetto, vkNetto);

  
  
  
  
  
  
  const wunschVkNetto = verkaufspreis(ekNetto, zielmarge);

  return {
    sku: artikel.sku,
    bezeichnung: artikel.bezeichnung,
    lieferantId: artikel.lieferantId,
    uvpNetto: Number.isFinite(deckel) ? cent(deckel) : null,
    ekNetto,
    vkNetto,
    vkBrutto: cent(vkNetto * (1 + UST_SATZ)),
    deckungsbeitragNetto: cent(vkNetto - ekNetto),
    rohmarge: marge,
    margeErreicht: marge >= MARGENUNTERGRENZE - 1e-9,
    zielmargeErreicht: vkNetto >= wunschVkNetto - 1e-9,
    amListendeckel: Number.isFinite(deckel) && vkNetto >= cent(deckel) - 1e-9,
    ekIstPlatzhalter: artikel.ekQuelle !== 'bestaetigt',
  };
}
















function fracht(positionen, lieferant) {
  const regel = lieferant.fracht;

  
  
  
  
  const warenwertNetto = cent(positionen.reduce((s, p) => s + p.vkNetto * p.menge, 0));
  const bestellwertNetto = cent(positionen.reduce((s, p) => s + p.ekNetto * p.menge, 0));

  if (regel.freiHausAbNetto != null && bestellwertNetto >= regel.freiHausAbNetto) {
    return {
      betragNetto: 0,
      grund: `frei Haus ab ${regel.freiHausAbNetto} € Bestellwert`,
      warenwertNetto,
      bestellwertNetto,
    };
  }

  const sperrgutPositionen = positionen.filter((p) => p.sperrgut).length;
  const betragNetto = cent(
    regel.pauschaleNetto + sperrgutPositionen * (regel.sperrgutZuschlagNetto ?? 0),
  );

  return {
    betragNetto,
    grund:
      sperrgutPositionen > 0
        ? `Pauschale plus ${sperrgutPositionen}× Sperrgutzuschlag`
        : 'Pauschale',
    warenwertNetto,
    bestellwertNetto,
  };
}










function mindestbestellwertErfuellt(bestellwertNetto, lieferant) {
  const grenze = lieferant.mindestbestellwertNetto ?? 0;
  return {
    erfuellt: bestellwertNetto >= grenze,
    grenze,
    bestellwertNetto,
    fehlbetragNetto: cent(Math.max(0, grenze - bestellwertNetto)),
  };
}











function ladeKatalog(daten, zielmarge) {
  const lieferantenById = new Map(daten.lieferanten.lieferanten.map((l) => [l.id, l]));

  const artikel = daten.artikel.artikel.map((a) => {
    const lieferant = lieferantenById.get(a.lieferantId);
    if (!lieferant) throw new Error(`Unbekannter Lieferant: ${a.lieferantId}`);
    return { ...a, ...kalkuliere(a, lieferant, zielmarge) };
  });

  return { artikel, lieferantenById };
}




















function istMenge(menge) {
  if (typeof menge !== 'number' || !Number.isFinite(menge) || menge <= 0) return false;
  return Math.abs(Math.round(menge * 100) - menge * 100) < 1e-9;
}

function berechneWarenkorb(zeilen, katalog) {
  const gruppen = new Map();

  for (const zeile of zeilen) {
    if (!istMenge(zeile.menge)) {
      throw new Error(`Ungültige Menge für ${zeile.sku}`);
    }
    const artikel = katalog.artikel.find((a) => a.sku === zeile.sku);
    if (!artikel) throw new Error(`Unbekannte Artikelnummer: ${zeile.sku}`);

    const position = {
      ...artikel,
      menge: zeile.menge,
      zeilensummeNetto: cent(artikel.vkNetto * zeile.menge),
      zeileneinkaufNetto: cent(artikel.ekNetto * zeile.menge),
    };

    if (!gruppen.has(artikel.lieferantId)) gruppen.set(artikel.lieferantId, []);
    gruppen.get(artikel.lieferantId).push(position);
  }

  const teillieferungen = [];
  for (const [lieferantId, positionen] of gruppen) {
    const lieferant = katalog.lieferantenById.get(lieferantId);
    const f = fracht(positionen, lieferant);
    
    
    const mbw = mindestbestellwertErfuellt(f.bestellwertNetto, lieferant);

    teillieferungen.push({
      lieferantId,
      lieferantName: lieferant.name,
      lieferzeitWerktage: lieferant.lieferzeitWerktage,
      positionen,
      warenwertNetto: f.warenwertNetto,
      einkaufNetto: f.bestellwertNetto,
      frachtNetto: f.betragNetto,
      frachtGrund: f.grund,
      mindestbestellwert: mbw,
      ...nebenkostenUntergrenze(positionen, lieferant),
    });
  }

  teillieferungen.sort((a, b) => a.lieferantId.localeCompare(b.lieferantId));

  const warenwertNetto = cent(teillieferungen.reduce((s, t) => s + t.warenwertNetto, 0));
  const frachtNetto = cent(teillieferungen.reduce((s, t) => s + t.frachtNetto, 0));
  const einkaufNetto = cent(teillieferungen.reduce((s, t) => s + t.einkaufNetto, 0));
  const nebenkostenUntergrenzeNetto = cent(
    teillieferungen.reduce((s, t) => s + (t.nebenkostenUntergrenzeNetto ?? 0), 0),
  );
  const summeNetto = cent(warenwertNetto + frachtNetto);
  const ust = cent(summeNetto * UST_SATZ);

  
  
  const mischmarge = warenwertNetto > 0 ? (warenwertNetto - einkaufNetto) / warenwertNetto : 0;

  return {
    teillieferungen,
    warenwertNetto,
    frachtNetto,
    einkaufNetto,
    nebenkostenUntergrenzeNetto,
    nebenkostenGrund: teillieferungen.map((t) => t.nebenkostenGrund).filter(Boolean),
    summeNetto,
    ust,
    summeBrutto: cent(summeNetto + ust),
    deckungsbeitragNetto: cent(warenwertNetto - einkaufNetto),
    mischmarge,
    mischmargeErreicht: mischmarge >= MARGENUNTERGRENZE - 1e-9,
    frachtanteilAmWarenwert: warenwertNetto > 0 ? frachtNetto / warenwertNetto : 0,
    bestellbar: teillieferungen.every((t) => t.mindestbestellwert.erfuellt),

    
    
    
    
    
    
    
    
    
    
    
    hinweise: teillieferungen
      .filter((t) => !t.mindestbestellwert.erfuellt)
      .map((t) => {
        const hebel = t.einkaufNetto > 0 ? t.warenwertNetto / t.einkaufNetto : 1;
        const fehlt = Math.ceil(t.mindestbestellwert.fehlbetragNetto * hebel);
        return (
          `${t.lieferantName}: Die Bestellmenge für diesen Hersteller ist noch zu klein. ` +
          `Es fehlen rund ${fehlt} € Warenwert netto.`
        );
      }),

    hinweiseIntern: teillieferungen
      .filter((t) => !t.mindestbestellwert.erfuellt)
      .map(
        (t) =>
          `${t.lieferantName}: Mindestbestellwert ${t.mindestbestellwert.grenze} € netto Bestellwert, ` +
          `erreicht sind ${t.mindestbestellwert.bestellwertNetto} €, es fehlen ` +
          `${t.mindestbestellwert.fehlbetragNetto} €.`,
      ),
  };
}































function nebenkostenUntergrenze(positionen, lieferant) {
  const n = lieferant?.nebenkosten;
  if (!n) return { nebenkostenUntergrenzeNetto: 0 };
  if (!positionen.some((p) => p.sperrgut)) return { nebenkostenUntergrenzeNetto: 0 };
  const palette = Number(n.paletteOebbNetto ?? 0);
  const folierung = Number(n.folierungNetto ?? 0);
  const summe = cent(palette + folierung);
  if (summe <= 0) return { nebenkostenUntergrenzeNetto: 0 };
  return {
    nebenkostenUntergrenzeNetto: summe,
    nebenkostenGrund: `mindestens eine Palette (${palette.toFixed(2)} €) und Folierung `
      + `(${folierung.toFixed(2)} €) je Lieferung mit palettierter Ware — Stückzahl unbekannt, `
      + 'Rückgabegutschrift nicht gegengerechnet',
  };
}














const ANSAETZE = {
  
  ueberlappung: 0.10,
  
  verschnitt: 0.05,
  
  aufkantungHoehe: 0.30,
  
  rohrabstand: 8,
  
  rohrZuschlag: 0.15,
  
  primerProM2: 0.30,
  
  dichtbandProDurchfuehrung: 1.0,
};

const aufrunden = (n) => Math.ceil(n - 1e-9);









function berechneBedarf(gebaeude, katalog) {
  const { laenge, breite, durchfuehrungen = 0, mitDrainage = false } = gebaeude;

  if (!(laenge > 0) || !(breite > 0)) throw new Error('Länge und Breite müssen positiv sein');
  if (!Number.isInteger(durchfuehrungen) || durchfuehrungen < 0) {
    throw new Error('Durchführungen müssen eine ganze Zahl ab 0 sein');
  }

  const flaeche = laenge * breite;
  const umfang = 2 * (laenge + breite);

  
  const aufkantung = umfang * ANSAETZE.aufkantungHoehe;
  const bahnBedarfM2 = (flaeche + aufkantung) * (1 + ANSAETZE.ueberlappung + ANSAETZE.verschnitt);

  const positionen = [];
  const hinweise = [];
  const nichtImSortiment = [];

  const nimm = (sku, menge, begruendung) => {
    const artikel = katalog.artikel.find((a) => a.sku === sku);
    if (!artikel) {
      
      
      
      
      nichtImSortiment.push(sku);
      return;
    }
    positionen.push({ sku, menge, bezeichnung: artikel.bezeichnung, begruendung });
  };

  
  const rolle = katalog.artikel.find((a) => a.sku === 'AB-RD-375');
  if (rolle) {
    const rollenflaeche = 37.5;
    const rollen = aufrunden(bahnBedarfM2 / rollenflaeche);
    const gelieferteFlaeche = rollen * rollenflaeche;
    const ueberschuss = gelieferteFlaeche - bahnBedarfM2;

    nimm(
      'AB-RD-375',
      rollen,
      `${bahnBedarfM2.toFixed(1)} m² Bedarf inkl. ${(aufkantung).toFixed(1)} m² Aufkantung, ` +
        `Überlappung und Verschnitt — Rollen zu ${rollenflaeche} m²`,
    );

    
    
    
    
    hinweise.push(
      `Rollenbindung: ${rollen} Rollen ergeben ${gelieferteFlaeche.toFixed(1)} m², ` +
        `das sind ${ueberschuss.toFixed(1)} m² über dem Bedarf ` +
        `(${((ueberschuss / bahnBedarfM2) * 100).toFixed(0)} %). Teilmengen gibt es nicht.`,
    );
  } else {
    
    
    nichtImSortiment.push('AB-RD-375');
  }

  const primerLiter = flaeche * ANSAETZE.primerProM2;
  nimm('AB-PR-010', aufrunden(primerLiter / 10), `${primerLiter.toFixed(1)} l bei ${ANSAETZE.primerProM2} l/m² — Gebinde zu 10 l`);

  
  const dichtbandMeter = umfang + durchfuehrungen * ANSAETZE.dichtbandProDurchfuehrung;
  nimm('ZB-DB-150', aufrunden(dichtbandMeter / 25), `${dichtbandMeter.toFixed(1)} m Umfang und Durchführungen — Rollen zu 25 m`);
  nimm('ZB-MA-SET', 1, 'ein Set Innen- und Außenecken je Gebäude');
  if (durchfuehrungen > 0) {
    nimm('ZB-RR-125', durchfuehrungen, `eine Ringraumdichtung je Durchführung`);
  }

  
  if (mitDrainage) {
    const rohrMeter = (flaeche / ANSAETZE.rohrabstand) * (1 + ANSAETZE.rohrZuschlag);
    nimm(
      'DR-100-050',
      aufrunden(rohrMeter / 50),
      `${rohrMeter.toFixed(1)} m bei ${ANSAETZE.rohrabstand} m Rohrabstand plus Zuschlag — Ringbund zu 50 m`,
    );
    nimm('DR-FT-SET', 1, 'ein Formteilset je Gebäude');
    nimm('DR-KS-100', 1, 'ein Kontrollschacht je Gebäude');
    nimm('DR-SL-100', 1, 'eine Steigleitung je Gebäude');
  } else {
    hinweise.push(
      'Ohne Radondrainage gerechnet. Sie ist nach ÖNORM S 5280-2 in den ' +
        'Radonschutzgebieten gefordert — im Zweifel die Gemeinde prüfen.',
    );
  }

  if (nichtImSortiment.length > 0) {
    hinweise.push(
      `Nicht im Sortiment und deshalb nicht enthalten: ${nichtImSortiment.join(', ')} — ` +
        'die Stückliste ist an diesen Stellen unvollständig.',
    );
  }

  hinweise.push('Planungswerte. Herstellerangaben und Ausführungsplanung gehen vor.');

  return {
    flaeche: Number(flaeche.toFixed(1)),
    umfang: Number(umfang.toFixed(1)),
    bahnBedarfM2: Number(bahnBedarfM2.toFixed(1)),
    positionen,
    hinweise,
    
    warenkorbzeilen: positionen.map((p) => ({ sku: p.sku, menge: p.menge })),
  };
}
















































const LIEFERGEBIET = Object.freeze({
  stand: '2026-08-26',
  herkunft: 'docs/baustoff-shop/liefergebiet-entschieden.md',
  land: 'AT',
  bezirke: Object.freeze([
    { name: 'Perg', bundesland: 'Oberösterreich', grund: 'Sitz des Betriebs (Marwach 5, 4312 Ried in der Riedmark)' },
    { name: 'Urfahr-Umgebung', bundesland: 'Oberösterreich', grund: 'Nachbarbezirk, Mühlviertel' },
    { name: 'Freistadt', bundesland: 'Oberösterreich', grund: 'Nachbarbezirk, Mühlviertel' },
    { name: 'Linz-Land', bundesland: 'Oberösterreich', grund: 'Ballungsraum, größte Bautätigkeit im Umkreis' },
    { name: 'Linz', bundesland: 'Oberösterreich', grund: 'Statutarstadt im selben Ballungsraum' },
  ]),
  vorbehalt:
    'Das tatsächliche Liefergebiet des Lieferanten ist unbekannt — aus fünfzehn Rechnungen '
    + 'nicht ableitbar, weil die Frachtpauschale nicht nach Entfernung staffelt. Beim '
    + 'Lieferanten zu erfragen; bis dahin gilt diese Liste als die engere der beiden.',
  selbstabholung:
    'Abholung am Betriebssitz ist von der Bezirksgrenze unberührt — sie setzt keine Lieferung voraus.',
});


const bezirksschluessel = (name) =>
  textZeile(name)
    .toLowerCase()
    .replace(/[\s.\-–—]+/g, '')
    .replace(/bezirk/g, '');

const GEBIETSSCHLUESSEL = new Set(LIEFERGEBIET.bezirke.map((b) => bezirksschluessel(b.name)));


function imLiefergebiet(bezirk) {
  const s = bezirksschluessel(bezirk ?? '');
  return s !== '' && GEBIETSSCHLUESSEL.has(s);
}


const bezirksliste = () => LIEFERGEBIET.bezirke.map((b) => b.name).join(', ');











function pruefeLieferort(ort = {}) {
  const land = textZeile(ort.land ?? '').toUpperCase();
  const bezirk = textZeile(ort.bezirk ?? '');

  if (land !== '' && land !== LIEFERGEBIET.land) {
    return {
      liefern: false,
      grund: `Lieferung nur innerhalb Österreichs, angegeben ist ${land}`,
    };
  }
  if (bezirk === '') {
    return {
      liefern: false,
      grund:
        'Bezirk der Baustelle fehlt — er lässt sich aus der Postleitzahl nicht bestimmen '
        + `und wird deshalb gefragt. Geliefert wird nach: ${bezirksliste()}.`,
    };
  }
  if (!imLiefergebiet(bezirk)) {
    return {
      liefern: false,
      grund:
        `Bezirk ${bezirk} liegt außerhalb des Liefergebiets. Geliefert wird nach: `
        + `${bezirksliste()}. Abholung am Betriebssitz ist davon unberührt.`,
    };
  }
  return { liefern: true, grund: null, bezirk };
}














const AT_UID = /^ATU\d{8}$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[a-zA-Z]{2,}$/;















const LIEFERLAND = 'AT';

const landVon = (wert) => String(wert ?? LIEFERLAND).trim().toUpperCase() || LIEFERLAND;








function uidPruefzifferStimmt(uid) {
  if (!AT_UID.test(uid)) return false;
  const z = uid.slice(3).split('').map(Number);
  let summe = 0;
  for (let i = 0; i < 7; i++) {
    if (i % 2 === 0) {
      summe += z[i];
    } else {
      const doppelt = z[i] * 2;
      summe += Math.floor(doppelt / 10) + (doppelt % 10);
    }
  }
  return (96 - summe) % 10 === z[7];
}

const pflicht = (wert) => typeof wert === 'string' && wert.trim().length > 0;























function pruefeBaustelle(baustelle) {
  const fehler = [];

  const strasse = String(baustelle.strasse ?? '').trim();
  const plz = String(baustelle.plz ?? '').trim();
  const ort = String(baustelle.ort ?? '').trim();
  const telefon = String(baustelle.telefon ?? '').trim();
  const name = String(baustelle.name ?? '').trim();
  const hinweis = String(baustelle.hinweis ?? '').trim();
  const bezirk = String(baustelle.bezirk ?? '').trim();
  
  
  
  
  const land = String(baustelle.land ?? '').trim().toUpperCase();

  if (!pflicht(strasse)) fehler.push('Baustelle: Straße und Hausnummer fehlen');
  if (!pflicht(ort)) fehler.push('Baustelle: Ort fehlt');
  if (!pflicht(telefon)) {
    fehler.push('Baustelle: Ansprechpartner vor Ort fehlt — die Spedition braucht eine Nummer');
  }

  for (const [bezeichnung, wert] of [
    ['Baustelle — Name', baustelle.name],
    ['Baustelle — Straße', baustelle.strasse],
    ['Baustelle — Ort', baustelle.ort],
    ['Baustelle — Ansprechpartner', baustelle.telefon],
    ['Baustelle — Hinweis', baustelle.hinweis],
  ]) {
    if (hatSteuerzeichen(wert)) {
      fehler.push(`${bezeichnung}: Zeilenumbrüche und Steuerzeichen sind hier nicht zulässig`);
    }
  }

  
  
  if (land === '') {
    fehler.push('Baustelle: Land fehlt — eine vierstellige Postleitzahl beweist nicht Österreich');
  } else if (land !== LIEFERLAND) {
    fehler.push(
      `Baustelle: Lieferung nur innerhalb Österreichs, angegeben ist ${land} — außerhalb ` +
        'wäre die Rechnung mit 20 % Umsatzsteuer falsch (Art 6, 7 UStG; Drittland: Ausfuhr)',
    );
  } else if (!/^\d{4}$/.test(plz) || Number(plz) < 1000) {
    fehler.push('Baustelle: Postleitzahl muss vierstellig und österreichisch sein');
  }

  
  
  
  
  
  
  if (land === LIEFERGEBIET.land) {
    const gebiet = pruefeLieferort({ land, bezirk });
    if (!gebiet.liefern) fehler.push(`Baustelle: ${gebiet.grund}`);
  }

  return { fehler, normalisiert: { name, strasse, plz, ort, bezirk, land, telefon, hinweis } };
}





function pruefeBestelldaten(daten = {}) {
  const fehler = [];
  const warnungen = [];

  const firma = String(daten.firma ?? '').trim();
  const uid = String(daten.uid ?? '').trim().toUpperCase().replace(/\s/g, '');
  const email = String(daten.email ?? '').trim();
  const strasse = String(daten.strasse ?? '').trim();
  const plz = String(daten.plz ?? '').trim();
  const ort = String(daten.ort ?? '').trim();
  const telefon = String(daten.telefon ?? '').trim();
  const land = landVon(daten.land);

  if (!pflicht(firma)) fehler.push('Firmenname fehlt');
  if (!pflicht(strasse)) fehler.push('Straße und Hausnummer fehlen');
  if (!pflicht(ort)) fehler.push('Ort fehlt');
  if (!pflicht(telefon)) fehler.push('Telefonnummer fehlt — die Spedition braucht sie für die Baustelle');

  
  
  
  
  
  
  
  
  
  for (const [name, wert] of [
    ['Firmenname', daten.firma],
    ['Straße', daten.strasse],
    ['Ort', daten.ort],
    ['Telefonnummer', daten.telefon],
    ['E-Mail-Adresse', daten.email],
  ]) {
    if (hatSteuerzeichen(wert)) {
      fehler.push(`${name}: Zeilenumbrüche und Steuerzeichen sind hier nicht zulässig`);
    }
  }

  if (land !== LIEFERLAND) {
    fehler.push(`Rechnungsanschrift außerhalb Österreichs (${land}) — dieser Shop bedient nur Österreich`);
  } else if (!/^\d{4}$/.test(plz) || Number(plz) < 1000) {
    fehler.push('Postleitzahl muss vierstellig und österreichisch sein');
  }

  if (!EMAIL.test(email)) fehler.push('E-Mail-Adresse fehlt oder ist unvollständig');

  
  if (daten.unternehmerBestaetigt !== true) {
    fehler.push('Bestätigung fehlt, dass die Bestellung für ein Unternehmen erfolgt (Gate 7)');
  }
  if (!AT_UID.test(uid)) {
    fehler.push('UID-Nummer fehlt oder hat nicht das Format ATU gefolgt von acht Ziffern');
  } else if (!uidPruefzifferStimmt(uid)) {
    warnungen.push(
      'Die Prüfziffer der UID passt nicht zum üblichen Verfahren. Verbindlich ist ' +
        'die Abfrage beim EU-Informationsaustauschsystem — bitte vor der Rechnung prüfen.',
    );
  }

  
  
  let baustelle = null;
  if (daten.baustelle) {
    const b = pruefeBaustelle(daten.baustelle);
    fehler.push(...b.fehler);
    baustelle = b.normalisiert;

    
    
    
    
    
    
    
    
    if (daten[ZUSICHERUNG_DRITTER.feld] !== true) {
      fehler.push(
        'Baustelle: Bestätigung fehlt, dass der Ansprechpartner vor Ort über die ' +
          'Weitergabe seiner Daten informiert wurde (Art. 14 DSGVO)',
      );
    }
    
    
    if (!baustelle.name) baustelle.name = firma;
  }

  return {
    gueltig: fehler.length === 0,
    fehler,
    warnungen,
    normalisiert: { firma, uid, email, strasse, plz, ort, land, telefon, baustelle },
  };
}





function baueAuftrag(bestellnummer, kundendaten, { zahlungEingegangen = false } = {}) {
  const { normalisiert } = pruefeBestelldaten(kundendaten);
  const b = normalisiert.baustelle;

  return {
    bestellnummer,
    zahlungEingegangen,
    kundeIstUnternehmer: kundendaten.unternehmerBestaetigt === true,
    uid: normalisiert.uid || null,
    absender: { firma: '— Firmendaten des Betreibers fehlen noch —' },
    
    
    lieferungAnRechnungsadresse: b === null,
    lieferadresse: b
      ? { name: b.name, strasse: b.strasse, plz: b.plz, ort: b.ort, telefon: b.telefon, hinweis: b.hinweis }
      : {
          name: normalisiert.firma,
          strasse: normalisiert.strasse,
          plz: normalisiert.plz,
          ort: normalisiert.ort,
          telefon: normalisiert.telefon,
          hinweis: '',
        },
  };
}















const REFERENZWERT = 300;


const MINDESTDAUER_MONATE = 6;

const GRENZEN = [
  'Diese Einordnung sagt nichts über Gesundheit oder persönliches Risiko aus. ' +
    'Dafür sind die Fachstelle für Radon und die zuständigen Stellen da.',
  'Verlässlich ist nur eine Messung durch eine ermächtigte Überwachungsstelle — ' +
    'etwa AGES oder das Strahlenschutzlabor der Stadt Wien.',
  'Welche Maßnahme im Einzelfall taugt, entscheidet die Bausubstanz, nicht der ' +
    'Messwert. Genannt ist die übliche Maßnahme, nicht eine Zusage.',
];






function ordneEin({ wert, messdauerMonate } = {}) {
  if (typeof wert !== 'number' || !Number.isFinite(wert) || wert < 0) {
    throw new Error('Messwert muss eine Zahl ab 0 sein');
  }
  if (typeof messdauerMonate !== 'number' || !Number.isFinite(messdauerMonate) || messdauerMonate <= 0) {
    throw new Error('Messdauer muss eine positive Zahl sein');
  }

  const istLangzeit = messdauerMonate >= MINDESTDAUER_MONATE;

  if (!istLangzeit) {
    return {
      wert,
      messdauerMonate,
      istLangzeit: false,
      stufe: 'kurzzeit',
      vergleichbar: false,
      ueberschreitung: null,
      istQualifizierterAnlass: false,
      titel: 'Hinweis, kein Ergebnis',
      aussage:
        `Eine Messung über ${messdauerMonate} Monate darf nicht mit dem Referenzwert ` +
        `von ${REFERENZWERT} Bq/m³ verglichen werden — dafür verlangt die ` +
        `Radonschutzverordnung mindestens ${MINDESTDAUER_MONATE} Monate.`,
      massnahme:
        'Langzeitmessung bei einer ermächtigten Überwachungsstelle veranlassen. ' +
        'Sie ist für Privathaushalte derzeit kostenlos.',
      grenzen: GRENZEN,
    };
  }

  
  
  
  
  
  
  if (wert <= REFERENZWERT) {
    return {
      wert,
      messdauerMonate,
      istLangzeit: true,
      stufe: 'unter',
      vergleichbar: true,
      ueberschreitung: false,
      istQualifizierterAnlass: false,
      titel: 'Referenzwert eingehalten',
      aussage:
        `${wert} Bq/m³ überschreiten den gesetzlichen Referenzwert von ${REFERENZWERT} Bq/m³ nicht. ` +
        'Eine Maßnahme ist nicht vorgeschrieben.',
      massnahme:
        'Der Referenzwert ist ein gesetzlicher Bezugswert, keine naturwissenschaftliche ' +
        'Schwelle. Eine Senkung ist auch darunter möglich und mit einfachen Mitteln oft ' +
        'günstig zu erreichen.',
      grenzen: GRENZEN,
    };
  }

  if (wert <= 1000) {
    return {
      wert,
      messdauerMonate,
      istLangzeit: true,
      stufe: 'ueber',
      vergleichbar: true,
      ueberschreitung: true,
      istQualifizierterAnlass: true,
      titel: 'Referenzwert überschritten',
      aussage:
        `${wert} Bq/m³ liegen über dem Referenzwert von ${REFERENZWERT} Bq/m³. ` +
        'Eine bauliche Sanierung wird empfohlen.',
      massnahme:
        'Übliche Maßnahme ist die Unterbodenabsaugung nach ÖNORM S 5280-3, ' +
        'ergänzend die Abdichtung erdberührter Bauteile.',
      grenzen: GRENZEN,
    };
  }

  return {
    wert,
    messdauerMonate,
    istLangzeit: true,
    stufe: 'deutlich',
    vergleichbar: true,
    ueberschreitung: true,
    istQualifizierterAnlass: true,
    titel: 'Deutliche Überschreitung',
    aussage:
      `${wert} Bq/m³ liegen weit über dem Referenzwert von ${REFERENZWERT} Bq/m³.`,
    massnahme:
      'Bauliche Sanierung empfohlen, Planung durch einen fachkundigen Betrieb, ' +
      'anschließend Wirksamkeitskontrolle durch Nachmessung.',
    grenzen: GRENZEN,
  };
}




















const IMPRESSUMSFELDER = [
  { feld: 'firma', bezeichnung: 'Name oder Firma laut Firmenbuch', bedingt: false },
  { feld: 'rechtsform', bezeichnung: 'Rechtsform', bedingt: false },
  { feld: 'strasse', bezeichnung: 'Geografische Anschrift der Niederlassung', bedingt: false },
  { feld: 'plz', bezeichnung: 'Postleitzahl', bedingt: false },
  { feld: 'ort', bezeichnung: 'Ort', bedingt: false },
  { feld: 'email', bezeichnung: 'E-Mail-Adresse für die rasche Kontaktaufnahme', bedingt: false },
  { feld: 'telefon', bezeichnung: 'Telefonnummer', bedingt: false },
  { feld: 'firmenbuchnummer', bezeichnung: 'Firmenbuchnummer', bedingt: true, wennEingetragen: true },
  { feld: 'firmenbuchgericht', bezeichnung: 'Firmenbuchgericht', bedingt: true, wennEingetragen: true },
  { feld: 'uid', bezeichnung: 'UID-Nummer', bedingt: true },
  { feld: 'gewerbebehoerde', bezeichnung: 'Zuständige Gewerbebehörde', bedingt: false },
  { feld: 'kammer', bezeichnung: 'Kammer- oder Berufsverbandszugehörigkeit', bedingt: false },
  { feld: 'gewerbewortlaut', bezeichnung: 'Wortlaut des angemeldeten Gewerbes', bedingt: false },
];






function pruefeBetreiberdaten(betreiber = {}) {
  const imFirmenbuch = betreiber.imFirmenbuch === true;
  const fehlend = [];

  for (const f of IMPRESSUMSFELDER) {
    if (f.wennEingetragen && !imFirmenbuch) continue;
    const wert = betreiber[f.feld];
    if (typeof wert !== 'string' || wert.trim() === '') fehlend.push(f);
  }

  return {
    vollstaendig: fehlend.length === 0,
    fehlend: fehlend.map((f) => f.bezeichnung),
    fehlendeFelder: fehlend.map((f) => f.feld),
    imFirmenbuch,
  };
}

const zeile = (betreiber, feld, bezeichnung) => {
  const wert = betreiber[feld];
  return typeof wert === 'string' && wert.trim() !== '' ? textZeile(wert) : LUECKE(bezeichnung);
};


function erzeugeImpressum(betreiber = {}) {
  const p = pruefeBetreiberdaten(betreiber);
  const zeilen = [
    'Impressum',
    'Informationen nach § 5 E-Commerce-Gesetz und § 14 Unternehmensgesetzbuch',
    '',
    zeile(betreiber, 'firma', 'Firma laut Firmenbuch'),
    zeile(betreiber, 'rechtsform', 'Rechtsform'),
    zeile(betreiber, 'strasse', 'Anschrift'),
    `${zeile(betreiber, 'plz', 'PLZ')} ${zeile(betreiber, 'ort', 'Ort')}`,
    'Österreich',
    '',
    `E-Mail: ${zeile(betreiber, 'email', 'E-Mail')}`,
    `Telefon: ${zeile(betreiber, 'telefon', 'Telefon')}`,
    '',
  ];

  if (p.imFirmenbuch) {
    zeilen.push(
      `Firmenbuchnummer: ${zeile(betreiber, 'firmenbuchnummer', 'Firmenbuchnummer')}`,
      `Firmenbuchgericht: ${zeile(betreiber, 'firmenbuchgericht', 'Firmenbuchgericht')}`,
    );
  } else {
    zeilen.push('Nicht im Firmenbuch eingetragen.');
  }

  zeilen.push(
    `UID-Nummer: ${zeile(betreiber, 'uid', 'UID')}`,
    `Gewerbe: ${zeile(betreiber, 'gewerbewortlaut', 'Gewerbewortlaut')}`,
    `Gewerbebehörde: ${zeile(betreiber, 'gewerbebehoerde', 'Gewerbebehörde')}`,
    `Kammerzugehörigkeit: ${zeile(betreiber, 'kammer', 'Kammer')}`,
    '',
    'Anwendbare Rechtsvorschrift: Gewerbeordnung, abrufbar über das',
    'Rechtsinformationssystem des Bundes.',
  );

  return { text: zeilen.join('\n'), vollstaendig: p.vollstaendig, fehlend: p.fehlend };
}














































