function trockenlauf(welt = WELT_HEUTE) {
  const protokoll = [];
  let minutenMensch = 0;
  let abbruchBei = null;

  for (const schritt of SCHRITTE) {
    const fehlend = schritt.braucht.filter((v) => welt[v] !== true);

    if (fehlend.length === 0) {
      protokoll.push({ id: schritt.id, name: schritt.name, stand: 'automatisch', minuten: 0, fehlend: [] });
      continue;
    }

    if (schritt.blockiert) {
      protokoll.push({
        id: schritt.id,
        name: schritt.name,
        stand: 'blockiert',
        minuten: 0,
        fehlend,
        grund: schritt.hinweis,
      });
      if (!abbruchBei) abbruchBei = schritt.id;
      continue;
    }

    minutenMensch += schritt.minutenOhne;
    protokoll.push({
      id: schritt.id,
      name: schritt.name,
      stand: 'handarbeit',
      minuten: schritt.minutenOhne,
      fehlend,
      grund: schritt.hinweis,
    });
  }

  return {
    protokoll,
    minutenMensch,
    laeuftDurch: abbruchBei === null && minutenMensch === 0,
    abbruchBei,
    blockaden: protokoll.filter((p) => p.stand === 'blockiert').map((p) => p.id),
  };
}








function engpaesse() {
  const voll = trockenlauf(WELT_AUSGEBAUT);
  const namen = Object.keys(WELT_AUSGEBAUT);

  return namen
    .map((fehlt) => {
      const welt = { ...WELT_AUSGEBAUT, [fehlt]: false };
      const lauf = trockenlauf(welt);
      return {
        faehigkeit: fehlt,
        zusatzminuten: lauf.minutenMensch - voll.minutenMensch,
        blockiert: lauf.blockaden,
        betroffeneSchritte: lauf.protokoll.filter((p) => p.stand !== 'automatisch').map((p) => p.id),
      };
    })
    .sort((a, b) => b.blockiert.length - a.blockiert.length || b.zusatzminuten - a.zusatzminuten);
}








function aufwandProMonat(welt, bestellungenProMonat) {
  const lauf = trockenlauf(welt);
  const minuten = lauf.minutenMensch * bestellungenProMonat;
  return {
    minutenJeBestellung: lauf.minutenMensch,
    bestellungenProMonat,
    stundenProMonat: Math.round((minuten / 60) * 10) / 10,
    blockaden: lauf.blockaden,
  };
}
























const VIES_ENDPUNKT = 'https://ec.europa.eu/taxation_customs/vies/rest-api/check-vat-number';

const STAND = {
  GUELTIG: 'gueltig',
  UNGUELTIG: 'ungueltig',
  UNBESTAETIGT: 'unbestaetigt',
};


const VORUEBERGEHEND = new Set([
  'MS_UNAVAILABLE',
  'MS_MAX_CONCURRENT_REQ',
  'SERVICE_UNAVAILABLE',
  'TIMEOUT',
  'SERVER_BUSY',
  'GLOBAL_MAX_CONCURRENT_REQ',
]);









const LAENDER = new Set([
  'AT', 'BE', 'BG', 'CY', 'CZ', 'DE', 'DK', 'EE', 'EL', 'ES', 'FI', 'FR', 'HR',
  'HU', 'IE', 'IT', 'LT', 'LU', 'LV', 'MT', 'NL', 'PL', 'PT', 'RO', 'SE', 'SI',
  'SK', 'XI',
]);








function zerlegeUid(uid) {
  const roh = String(uid ?? '').toUpperCase().replace(/[\s.-]/g, '');
  const treffer = /^([A-Z]{2})([0-9A-Z+*]{2,13})$/.exec(roh);
  if (!treffer || !LAENDER.has(treffer[1])) return null;
  return { land: treffer[1], nummer: treffer[2] };
}









function baueAnfrage(uid, { eigeneUid = null } = {}) {
  const teil = zerlegeUid(uid);
  if (!teil) throw new Error(`Keine auswertbare UID: ${uid}`);

  const koerper = { countryCode: teil.land, vatNumber: teil.nummer };

  if (eigeneUid) {
    const eigen = zerlegeUid(eigeneUid);
    if (!eigen) throw new Error(`Keine auswertbare eigene UID: ${eigeneUid}`);
    koerper.requesterMemberStateCode = eigen.land;
    koerper.requesterNumber = eigen.nummer;
  }

  return { url: VIES_ENDPUNKT, methode: 'POST', koerper, qualifiziert: Boolean(eigeneUid) };
}








function werteAntwortAus(antwort) {
  if (!antwort || typeof antwort !== 'object') {
    return { stand: STAND.UNBESTAETIGT, grund: 'Keine auswertbare Antwort', wiederholbar: true };
  }

  const fehler = antwort.userError ?? antwort.errorWrappers?.[0]?.error ?? null;

  if (fehler && fehler !== 'VALID' && fehler !== 'INVALID') {
    return {
      stand: STAND.UNBESTAETIGT,
      grund: `Dienst meldet ${fehler}`,
      wiederholbar: VORUEBERGEHEND.has(fehler),
    };
  }

  if (typeof antwort.isValid !== 'boolean') {
    return {
      stand: STAND.UNBESTAETIGT,
      grund: 'Antwort ohne verwertbares Gültigkeitskennzeichen',
      wiederholbar: true,
    };
  }

  return {
    stand: antwort.isValid ? STAND.GUELTIG : STAND.UNGUELTIG,
    name: antwort.name && antwort.name !== '---' ? antwort.name : null,
    anschrift: antwort.address && antwort.address !== '---' ? antwort.address : null,
    abfrageId: antwort.requestIdentifier || null,
    abfrageDatum: antwort.requestDate || null,
    grund: antwort.isValid ? 'Vom Mitgliedstaat bestätigt' : 'Vom Mitgliedstaat als ungültig gemeldet',
    wiederholbar: false,
  };
}









async function pruefeUid(uid, { abruf, eigeneUid = null, versuche = 3 } = {}) {
  if (typeof abruf !== 'function') throw new Error('pruefeUid braucht einen Abruf');

  const anfrage = baueAnfrage(uid, { eigeneUid });
  let letzte = { stand: STAND.UNBESTAETIGT, grund: 'Nicht ausgeführt', wiederholbar: true };

  for (let versuch = 1; versuch <= versuche; versuch++) {
    let auswertung;
    try {
      auswertung = werteAntwortAus(await abruf(anfrage));
    } catch (fehler) {
      auswertung = { stand: STAND.UNBESTAETIGT, grund: `Abruf gescheitert: ${fehler.message}`, wiederholbar: true };
    }

    letzte = { ...auswertung, versuche: versuch, qualifiziert: anfrage.qualifiziert };
    if (!auswertung.wiederholbar) return letzte;
  }

  return letzte;
}








function belegzeile(auswertung, uid) {
  const teile = [
    `UID ${uid}`,
    auswertung.stand,
    auswertung.abfrageDatum ?? 'ohne Datum',
    auswertung.abfrageId ? `Abfrage-ID ${auswertung.abfrageId}` : 'ohne Abfrage-ID — nicht als Nachweis geeignet',
  ];
  if (auswertung.name) teile.push(auswertung.name);
  
  
  
  
  
  return textZeile(teile.join(' · '));
}










function ergaenzeFreigabe(freigabe, auswertung) {
  const gruende = [...freigabe.gruende];

  if (auswertung.stand === STAND.UNGUELTIG) {
    gruende.push('UID vom Mitgliedstaat als ungültig gemeldet — Gate 7 nicht erfüllt');
  } else if (auswertung.stand !== STAND.GUELTIG) {
    gruende.push(`UID nicht bestätigt (${auswertung.grund}) — Bestellung wartet, sie ist nicht abgelehnt`);
  } else if (!auswertung.abfrageId) {
    gruende.push('UID bestätigt, aber ohne Abfrage-Identifikation — kein vorlegbarer Nachweis');
  }

  return { erlaubt: gruende.length === 0, gruende, uidStand: auswertung.stand };
}






























const AUFBEWAHRUNG_JAHRE = 7;

const ARTEN = {
  angebot: { kuerzel: 'AN', nummernkreis: true },
  rechnung: { kuerzel: 'RE', nummernkreis: true },
  gutschrift: { kuerzel: 'GS', nummernkreis: true },
  lieferantenbestellung: { kuerzel: 'LB', nummernkreis: true },
  uidabfrage: { kuerzel: 'UP', nummernkreis: false },
  vermerk: { kuerzel: 'VM', nummernkreis: false },
};















const FELDER_DER_ABLAGE = Object.freeze({
  lfd: {
    verlangt: true,
    grundlage: '§ 131 Abs 1 Z 2 BAO',
    zweck: 'Eintragungen der Zeitfolge nach — die laufende Nummer macht Lücken und Umsortierungen sichtbar',
  },
  art: {
    verlangt: true,
    grundlage: '§ 131 BAO',
    zweck: 'welche Aufzeichnung vorliegt; ohne die Art ist kein Nummernkreis prüfbar',
  },
  nummer: {
    verlangt: true,
    grundlage: '§ 11 Abs 1 Z 5 UStG',
    zweck: 'die fortlaufende, einmalige Belegnummer',
  },
  zeitpunkt: {
    verlangt: true,
    grundlage: '§ 11 UStG, § 131 Abs 1 Z 2 BAO',
    zweck: 'Ausstellungsdatum; zeitgerechte Eintragung in der Zeitfolge',
  },
  vorgang: {
    verlangt: true,
    grundlage: '§ 131 Abs 1 Z 5 BAO',
    zweck: 'Rückführbarkeit zum Geschäftsfall — die Vorgangsakte ist die geordnete Belegablage',
  },
  betragNetto: {
    verlangt: true,
    grundlage: '§ 11 Abs 1 Z 5 UStG',
    zweck: 'das Entgelt',
  },
  betragBrutto: {
    verlangt: true,
    grundlage: '§ 11 UStG',
    zweck: 'Entgelt samt Steuer; die Differenz zum Netto ist der ausgewiesene Steuerbetrag',
  },
  text: {
    verlangt: false,
    grundlage: 'betrieblich',
    zweck: 'Betreff oder Vermerk — nie der volle Belegtext; Schranke: keine Daten Dritter (pruefeAblageAufDrittdaten)',
  },
  bezugAuf: {
    verlangt: true,
    grundlage: '§ 131 Abs 1 Z 6 BAO',
    zweck: 'die Stornokette: der ursprüngliche Inhalt bleibt feststellbar, weil die Gutschrift auf die Rechnung zeigt, statt sie zu ändern',
  },
});










function neueAblage({ zaehler = {}, schreibe = null } = {}) {
  return { eintraege: [], zaehler: { ...zaehler }, schreibe };
}

const schluessel = (art, jahr) => `${art}:${jahr}`;









function naechsteNummer(ablage, art, jahr) {
  const beschreibung = ARTEN[art];
  if (!beschreibung) throw new Error(`Unbekannte Vorgangsart: ${art}`);
  if (!beschreibung.nummernkreis) throw new Error(`${art} führt keinen Nummernkreis`);
  if (!Number.isInteger(jahr)) throw new Error('Die Nummernvergabe braucht ein Jahr');

  const k = schluessel(art, jahr);
  const naechste = (ablage.zaehler[k] ?? 0) + 1;
  const nummer = `${beschreibung.kuerzel}-${jahr}-${String(naechste).padStart(4, '0')}`;

  
  
  
  ablage.schreibe?.({ typ: 'nummernvergabe', art, jahr, nummer });
  ablage.zaehler[k] = naechste;
  return nummer;
}





function haltefest(ablage, eintrag) {
  if (!ARTEN[eintrag.art]) throw new Error(`Unbekannte Vorgangsart: ${eintrag.art}`);
  if (!eintrag.zeitpunkt) throw new Error('Jeder Eintrag braucht einen Zeitpunkt');

  const fertig = Object.freeze({
    lfd: ablage.eintraege.length + 1,
    art: eintrag.art,
    nummer: eintrag.nummer ?? null,
    zeitpunkt: eintrag.zeitpunkt,
    vorgang: eintrag.vorgang ?? null,
    betragNetto: eintrag.betragNetto ?? null,
    betragBrutto: eintrag.betragBrutto ?? null,
    text: eintrag.text ?? '',
    bezugAuf: eintrag.bezugAuf ?? null,
  });

  ablage.schreibe?.({ typ: 'eintrag', eintrag: fertig });
  ablage.eintraege.push(fertig);
  return fertig;
}








function stelleRechnungAus(ablage, rechnung, { zeitpunkt, jahr, vorgang }) {
  if (!rechnung.vollstaendig) {
    return {
      ausgestellt: false,
      grund: `Pflichtangaben fehlen: ${rechnung.fehlend.join(', ')} — keine Nummer vergeben`,
    };
  }

  const nummer = naechsteNummer(ablage, 'rechnung', jahr);
  const eintrag = haltefest(ablage, {
    art: 'rechnung',
    nummer,
    zeitpunkt,
    vorgang,
    betragNetto: rechnung.nettobetrag ?? null,
    betragBrutto: rechnung.bruttobetrag ?? null,
    text: rechnung.text ?? '',
  });

  return { ausgestellt: true, nummer, eintrag };
}









function storniere(ablage, nummer, { grund, zeitpunkt, jahr }) {
  const ziel = ablage.eintraege.find((e) => e.nummer === nummer);
  if (!ziel) throw new Error(`Kein Eintrag mit der Nummer ${nummer}`);
  if (istStorniert(ablage, nummer)) {
    throw new Error(`${nummer} ist bereits storniert`);
  }

  const gutschrift = naechsteNummer(ablage, 'gutschrift', jahr);
  return haltefest(ablage, {
    art: 'gutschrift',
    nummer: gutschrift,
    zeitpunkt,
    vorgang: ziel.vorgang,
    betragNetto: ziel.betragNetto === null ? null : -ziel.betragNetto,
    betragBrutto: ziel.betragBrutto === null ? null : -ziel.betragBrutto,
    text: `Storno zu ${nummer}: ${grund}`,
    bezugAuf: nummer,
  });
}


function vorgangsakte(ablage, vorgang) {
  return ablage.eintraege.filter((e) => e.vorgang === vorgang);
}







function pruefeNummernkreis(ablage, art, jahr) {
  const kuerzel = ARTEN[art]?.kuerzel;
  if (!kuerzel) throw new Error(`Unbekannte Vorgangsart: ${art}`);

  const vorsatz = `${kuerzel}-${jahr}-`;
  const vergeben = ablage.eintraege
    .filter((e) => e.nummer?.startsWith(vorsatz))
    .map((e) => Number(e.nummer.slice(vorsatz.length)))
    .sort((a, b) => a - b);

  const hoechste = ablage.zaehler[schluessel(art, jahr)] ?? 0;
  const fehlend = [];
  for (let i = 1; i <= hoechste; i++) {
    if (!vergeben.includes(i)) fehlend.push(`${vorsatz}${String(i).padStart(4, '0')}`);
  }

  return { anzahl: vergeben.length, hoechste, fehlend, lueckenlos: fehlend.length === 0 };
}





function aufbewahrungBis(jahr) {
  if (!Number.isInteger(jahr)) throw new Error('Die Frist braucht ein Jahr');
  return { jahr: jahr + AUFBEWAHRUNG_JAHRE, hinweis: `31.12.${jahr + AUFBEWAHRUNG_JAHRE} (§ 132 BAO)` };
}







function istStorniert(ablage, nummer) {
  return ablage.eintraege.some((e) => e.art === 'gutschrift' && e.bezugAuf === nummer);
}















function pruefeAblagefelder(ablage) {
  const bekannt = Object.keys(FELDER_DER_ABLAGE);
  const funde = [];

  for (const e of ablage.eintraege) {
    const vorhanden = Object.keys(e);
    for (const feld of vorhanden) {
      if (!bekannt.includes(feld)) {
        funde.push(`Eintrag ${e.lfd ?? '?'}: Feld „${feld}" hat keinen Verzeichniseintrag`);
      }
    }
    for (const feld of bekannt) {
      if (!vorhanden.includes(feld)) {
        funde.push(`Eintrag ${e.lfd ?? '?'}: Verzeichnisfeld „${feld}" fehlt — der Eintrag kam an haltefest vorbei`);
      }
    }
  }

  return { dicht: funde.length === 0, funde, geprueft: ablage.eintraege.length };
}


function alsCsv(ablage) {
  const kopf = 'lfd;art;nummer;zeitpunkt;vorgang;netto;brutto;bezug;text';
  const zeilen = ablage.eintraege.map((e) =>
    [
      e.lfd,
      e.art,
      e.nummer ?? '',
      e.zeitpunkt,
      e.vorgang ?? '',
      e.betragNetto ?? '',
      e.betragBrutto ?? '',
      e.bezugAuf ?? '',
      csvFeld(e.text).slice(0, 200),
    ].join(';'),
  );
  return [kopf, ...zeilen].join('\n');
}



















































function journalzeile(ereignis) {
  if (ereignis?.typ !== 'nummernvergabe' && ereignis?.typ !== 'eintrag') {
    throw new Error(`Unbekannter Zeilentyp für das Journal: ${ereignis?.typ}`);
  }
  return JSON.stringify(ereignis).replace(/[\u007F\u0085\u2028\u2029]/g, (z) => {
    return '\\u' + z.charCodeAt(0).toString(16).padStart(4, '0');
  });
}

const kreis = (art, jahr) => `${art}:${jahr}`;


function hebeZaehler(ablage, art, nummer, zeilennummer) {
  const teile = String(nummer).split('-');
  const laufend = Number(teile.at(-1));
  const jahr = Number(teile.at(-2));
  if (!Number.isInteger(laufend) || laufend < 1 || !Number.isInteger(jahr)) {
    throw new Error(`Journal, Zeile ${zeilennummer}: ${nummer} ist keine lesbare Belegnummer`);
  }
  const k = kreis(art, jahr);
  ablage.zaehler[k] = Math.max(ablage.zaehler[k] ?? 0, laufend);
}













function ausJournal(journal, { schreibe = null } = {}) {
  const ablage = neueAblage({ schreibe });
  const bekannt = Object.keys(FELDER_DER_ABLAGE);

  const zeilen = String(journal ?? '').split('\n');
  for (let i = 0; i < zeilen.length; i++) {
    const roh = zeilen[i].trim();
    if (!roh) continue;
    const nr = i + 1;

    let ereignis;
    try {
      ereignis = JSON.parse(roh);
    } catch {
      throw new Error(`Journal, Zeile ${nr}: kein gültiges JSON`);
    }

    if (ereignis.typ === 'nummernvergabe') {
      if (!ARTEN[ereignis.art]) {
        throw new Error(`Journal, Zeile ${nr}: unbekannte Vorgangsart ${ereignis.art}`);
      }
      hebeZaehler(ablage, ereignis.art, ereignis.nummer, nr);
      continue;
    }

    if (ereignis.typ === 'eintrag') {
      const eintrag = ereignis.eintrag ?? {};
      const vorhanden = Object.keys(eintrag);
      for (const feld of vorhanden) {
        if (!bekannt.includes(feld)) {
          throw new Error(
            `Journal, Zeile ${nr}: Feld „${feld}" hat keinen Verzeichniseintrag — das Laden ist eine Migrationsfrage geworden`,
          );
        }
      }
      for (const feld of bekannt) {
        if (!vorhanden.includes(feld)) {
          throw new Error(
            `Journal, Zeile ${nr}: Verzeichnisfeld „${feld}" fehlt — das Laden ist eine Migrationsfrage geworden`,
          );
        }
      }
      if (!ARTEN[eintrag.art]) {
        throw new Error(`Journal, Zeile ${nr}: unbekannte Vorgangsart ${eintrag.art}`);
      }
      if (eintrag.lfd !== ablage.eintraege.length + 1) {
        throw new Error(
          `Journal, Zeile ${nr}: lfd ${eintrag.lfd} statt ${ablage.eintraege.length + 1} — die Zeitfolge ist gerissen`,
        );
      }

      ablage.eintraege.push(Object.freeze({ ...eintrag }));
      
      
      if (eintrag.nummer) hebeZaehler(ablage, eintrag.art, eintrag.nummer, nr);
      continue;
    }

    throw new Error(`Journal, Zeile ${nr}: unbekannter Zeilentyp ${ereignis.typ}`);
  }

  return ablage;
}





















const SKONTO_SATZ = 0.03;
const SKONTO_FRIST_TAGE = 14;














function skontoErsparnis(einkaufNetto, satz = SKONTO_SATZ) {
  if (satz < 0 || satz >= 1) throw new Error('Skontosatz muss zwischen 0 und 1 liegen');
  return cent(Math.max(0, einkaufNetto) * satz);
}





























function zahlungszielTraegt({ kundenzielTage, skontofristTage = SKONTO_FRIST_TAGE, bearbeitungstage = 2 }) {
  if (!Number.isFinite(kundenzielTage) || kundenzielTage < 0) {
    throw new Error('Kundenzahlungsziel muss eine Zahl ab null sein');
  }
  
  
  const spaetesterAusgang = kundenzielTage + bearbeitungstage;
  const traegt = spaetesterAusgang <= skontofristTage;

  const gruende = [];
  if (!traegt) {
    gruende.push(
      `Zahlungsziel ${kundenzielTage} Tage plus ${bearbeitungstage} Tage Bearbeitung ` +
        `überschreitet die Skontofrist von ${skontofristTage} Tagen um ` +
        `${spaetesterAusgang - skontofristTage} Tage — das Skonto ist dann nicht zu holen, ` +
        'ohne die Differenz vorzufinanzieren.',
    );
  }

  return { traegt, kundenzielTage, skontofristTage, bearbeitungstage, spaetesterAusgang, gruende };
}
























function skontoGegenGebuehr(bestellung, zahlwegId, opt = {}) {
  const { warenwertNetto, frachtNetto = 0, einkaufNetto } = bestellung;
  const { skontoSatz = SKONTO_SATZ, ust = 0.2, bearbeitungstage = 2 } = opt;
  const z = opt.zahlweg ?? null;
  if (!z) throw new Error('skontoGegenGebuehr braucht den Zahlweg als opt.zahlweg');

  const frist = zahlungszielTraegt({ kundenzielTage: z.tageBisEingang, bearbeitungstage });
  
  
  const skontoNetto = frist.traegt ? skontoErsparnis(einkaufNetto, skontoSatz) : 0;
  const bruttobetrag = cent((warenwertNetto + frachtNetto) * (1 + ust));
  const gebuehrBrutto = cent(bruttobetrag * z.prozent + z.fixEuro);

  return {
    zahlweg: zahlwegId,
    name: z.name,
    haeltFrist: frist.traegt,
    skontoNetto,
    gebuehrBrutto,
    
    netto: cent(skontoNetto - gebuehrBrutto),
    bemessungSkonto: cent(einkaufNetto),
    bemessungGebuehr: bruttobetrag,
  };
}































